class Solution:
    def calculateScore(self, s: str) -> int:
        stacks = [[] for _ in range(26)]
        score = 0
        for i, ch in enumerate(s):
            x = ord(ch) - ord('a')
            m = 25 - x
            if stacks[m]:
                j = stacks[m].pop()
                score += i - j
            else:
                stacks[x].append(i)
        return score
