import json
from hypothesis import strategies as st

def _mirror(c):
    return chr(ord('a') + ord('z') - ord(c))

@st.composite
def gen(draw):
    alphabet = draw(st.sampled_from([
        "abcdefghijklmnopqrstuvwxyz",
        "az",
        "ayz",
        "abyz",
        "aaaz",
        "a",
        "mn",
    ]))
    n = draw(st.integers(1, 12))
    s = draw(st.lists(st.sampled_from(list(alphabet)), min_size=n, max_size=n))
    return json.dumps("".join(s))

def validate(inp):
    try:
        s = json.loads(inp)
    except Exception:
        return False
    if not isinstance(s, str):
        return False
    if not (1 <= len(s) <= 10**5):
        return False
    return all('a' <= c <= 'z' for c in s)

def ref(inp):
    s = json.loads(inp)
    n = len(s)
    marked = [False] * n
    total = 0
    for i in range(n):
        target = _mirror(s[i])
        found = -1
        for j in range(i - 1, -1, -1):
            if not marked[j] and s[j] == target:
                found = j
                break
        if found != -1:
            marked[found] = True
            marked[i] = True
            total += i - found
    return json.dumps(total)
